alter table public.plate_art_templates add column wifi_qr_config jsonb not null default '{"x":70,"y":76,"size":27,"margin":4}'::jsonb check (jsonb_typeof(wifi_qr_config) = 'object');
alter table public.nfc_plates add column wifi_public_code text, add column url_destination text check (url_destination is null or url_destination ~ '^https?://[^[:space:]]+$');
update public.nfc_plates set wifi_public_code = encode(extensions.gen_random_bytes(12), 'hex') where wifi_public_code is null;
alter table public.nfc_plates alter column wifi_public_code set not null, add constraint nfc_plates_wifi_public_code_key unique (wifi_public_code), add constraint nfc_plates_wifi_public_code_check check (wifi_public_code ~ '^[a-f0-9]{24}$');
update public.plate_art_templates set qr_config = '{"x":30,"y":76,"size":27,"margin":4}'::jsonb, wifi_qr_config = '{"x":70,"y":76,"size":27,"margin":4}'::jsonb where id in ('6d613645-4ba2-4f4b-a9c1-0a0fd8a03d31', '7eb75a5f-d72a-4a3e-8654-852393d93d0b');
alter table public.nfc_plate_history drop constraint nfc_plate_history_action_check;
alter table public.nfc_plate_history add constraint nfc_plate_history_action_check check (action in ('created','reserved','activated','disabled','released','reassigned','destination_changed'));
create or replace function public.create_nfc_plate_batch(requested_template_id uuid, requested_quantity integer) returns jsonb language plpgsql security definer set search_path = public as $$ declare b public.plate_batches; p public.nfc_plates; c text; begin if not public.is_platform_admin() then return null; end if; if requested_quantity not between 1 and 200 then raise exception 'Quantity must be between 1 and 200'; end if; insert into public.plate_batches (batch_number,template_id,quantity,created_by) values ('LT-'||to_char(now(),'YYYYMMDD')||'-'||lpad(nextval('public.plate_batch_number_seq')::text,6,'0'),requested_template_id,requested_quantity,auth.uid()) returning * into b; for i in 1..requested_quantity loop c := 'PL-'||lpad(nextval('public.nfc_plate_number_seq')::text,6,'0'); insert into public.nfc_plates(public_code,wifi_public_code,display_code,batch_id) values(encode(extensions.gen_random_bytes(12),'hex'),encode(extensions.gen_random_bytes(12),'hex'),c,b.id) returning * into p; insert into public.nfc_plate_history(plate_id,action,next_status,changed_by,metadata) values(p.id,'created','available',auth.uid(),jsonb_build_object('batch_id',b.id)); end loop; return jsonb_build_object('id',b.id,'batch_number',b.batch_number,'quantity',b.quantity); end; $$;
create or replace function public.configure_nfc_plate_url_target(requested_plate_id uuid, requested_url_destination text default null) returns public.nfc_plates language plpgsql security definer set search_path = public as $$ declare p public.nfc_plates; u public.nfc_plates; d text := nullif(btrim(requested_url_destination),''); begin if not public.is_platform_admin() then raise exception 'Access denied'; end if; if d is not null and d !~ '^https?://[^[:space:]]+$' then raise exception 'Invalid URL'; end if; select * into p from public.nfc_plates where id=requested_plate_id for update; if not found then raise exception 'Plate not found'; end if; update public.nfc_plates set url_destination=d where id=p.id returning * into u; insert into public.nfc_plate_history(plate_id,action,previous_status,next_status,previous_tenant_id,next_tenant_id,changed_by,metadata) values(u.id,'destination_changed',p.status,u.status,p.tenant_id,u.tenant_id,auth.uid(),jsonb_build_object('url_configured',d is not null)); return u; end; $$;
create or replace function public.resolve_nfc_plate_destination(requested_code text) returns jsonb language sql stable security definer set search_path=public as $$ select jsonb_build_object('kind',case when p.url_destination is null then 'tenant_page' else 'url' end,'value',coalesce(p.url_destination,t.public_slug::text)) from public.nfc_plates p join public.tenants t on t.id=p.tenant_id where p.public_code=lower(btrim(requested_code)) and p.status='active' and t.status='active' limit 1; $$;
create or replace function public.resolve_nfc_plate_wifi(requested_code text) returns jsonb language sql stable security definer set search_path=public as $$ select jsonb_build_object('ssid',w.ssid,'password',w.password,'security_type',w.security_type,'hidden',w.hidden,'tenant_name',t.name) from public.nfc_plates p join public.tenants t on t.id=p.tenant_id join public.wifi_settings w on w.tenant_id=t.id where p.wifi_public_code=lower(btrim(requested_code)) and p.status='active' and t.status='active' limit 1; $$;
revoke all on function public.configure_nfc_plate_url_target(uuid,text) from public; revoke all on function public.resolve_nfc_plate_destination(text) from public; revoke all on function public.resolve_nfc_plate_wifi(text) from public; grant execute on function public.create_nfc_plate_batch(uuid,integer), public.configure_nfc_plate_url_target(uuid,text) to authenticated; grant execute on function public.resolve_nfc_plate_destination(text), public.resolve_nfc_plate_wifi(text) to anon,authenticated;
